/// <reference types="svelte" />
export type MasteryProfileTab = 'profil' | 'fetiche';

class MasteryProfileTabStore {
  active: MasteryProfileTab = $state('profil');
}

export const masteryProfileTab = new MasteryProfileTabStore();

export function setMasteryProfileTab(tab: MasteryProfileTab): void {
  masteryProfileTab.active = tab;
}

export function isMasteryFetichePanelVisible(): boolean {
  const modal = document.getElementById('masteryModal');
  const panel = document.getElementById('masteryFetichePanel');
  return !!(
    modal?.classList.contains('show')
    && panel
    && !panel.hidden
  );
}
